let currentRoute = 'lorient-groix';
let currentDay = 1;

function openOverlay(overlay) {
    overlay.classList.add('active');
    document.body.style.overflow = 'hidden';
    
    // animations trop smooth!
    if (overlay === overlayTickets) {
        document.querySelector('.bottom-content').style.opacity = '0';
        document.querySelector('header').style.opacity = '0';
    }
}

function closeOverlay(overlay) {
    overlay.classList.remove('active');
    document.body.style.overflow = '';
    
    // montrer le contenu des billlets :D
    if (overlay === overlayTickets) {
        document.querySelector('.bottom-content').style.opacity = '1';
        document.querySelector('header').style.opacity = '1';
    }
}

function updateSchedule() {
    const times = schedules[currentRoute][currentDay];
    const container = document.getElementById('scheduleTimes');
    container.innerHTML = times.map(time => `<button class="time-slot" type="button">${time}</button>`).join('');
    document.getElementById('currentDay').textContent = currentDay;
}

// ouvrir les overlays ^_^
btnAcheter.addEventListener('click', () => openOverlay(overlayAcheter));
btnDisponibilites.addEventListener('click', () => {
    openOverlay(overlayDisponibilites);
    updateSchedule();
});

menuAbout.addEventListener('click', (e) => {
    e.preventDefault();
    openOverlay(overlayAbout);
    hamburger.classList.remove('active');
    menu.classList.remove('active');
});

menuServices.addEventListener('click', (e) => {
    e.preventDefault();
    openOverlay(overlayServices);
    hamburger.classList.remove('active');
    menu.classList.remove('active');
});

menuContact.addEventListener('click', (e) => {
    e.preventDefault();
    openOverlay(overlayContact);
    hamburger.classList.remove('active');
    menu.classList.remove('active');
});

menuTickets.addEventListener('click', (e) => {
    e.preventDefault();
    openOverlay(overlayTickets);
    hamburger.classList.remove('active');
    menu.classList.remove('active');
});

// fermer les overlays ^_^
closeAcheter.addEventListener('click', () => closeOverlay(overlayAcheter));
closeDisponibilites.addEventListener('click', () => closeOverlay(overlayDisponibilites));
closeAbout.addEventListener('click', () => closeOverlay(overlayAbout));
closeServices.addEventListener('click', () => closeOverlay(overlayServices));
closeContact.addEventListener('click', () => closeOverlay(overlayContact));
closeTickets.addEventListener('click', () => closeOverlay(overlayTickets));

[overlayAcheter, overlayDisponibilites, overlayAbout, overlayServices, overlayContact, overlayTickets].forEach(overlay => {
    overlay.querySelector('.overlay-backdrop').addEventListener('click', () => closeOverlay(overlay));
});

document.addEventListener('keydown', (e) => {
    if (e.key === 'Escape') {
        closeOverlay(overlayAcheter);
        closeOverlay(overlayDisponibilites);
        closeOverlay(overlayAbout);
        closeOverlay(overlayServices);
        closeOverlay(overlayContact);
        closeOverlay(overlayTickets);
    }
});

document.querySelectorAll('.route-btn').forEach(btn => {
    btn.addEventListener('click', () => {
        document.querySelectorAll('.route-btn').forEach(b => {
            b.classList.remove('active');
            b.setAttribute('aria-pressed', 'false');
        });
        btn.classList.add('active');
        btn.setAttribute('aria-pressed', 'true');
        currentRoute = btn.dataset.route;
        updateSchedule();
    });
});

document.getElementById('prevDay').addEventListener('click', () => {
    currentDay = currentDay > 1 ? currentDay - 1 : 30;
    updateSchedule();
});

document.getElementById('nextDay').addEventListener('click', () => {
    currentDay = currentDay < 30 ? currentDay + 1 : 1;
    updateSchedule();
});

// Fonctions pour la recherche de réservation et l'affichage des billets :3
const API_BASE_URL = 'https://can.iutrs.unistra.fr/api';

btnSearchReservation.addEventListener('click', (e) => {
    e.preventDefault();
    searchReservation();
});

reservationIdInput.addEventListener('keypress', (e) => {
    if (e.key === 'Enter') {
        searchReservation();
    }
});

btnReload.addEventListener('click', () => {
    resetTicketsView();
});

btnRetry.addEventListener('click', () => {
    resetTicketsView();
});

function resetTicketsView() {
    reservationInputZone.style.display = 'block';
    loadingSpinner.style.display = 'none';
    ticketsDisplay.style.display = 'none';
    errorMessage.style.display = 'none';
    reservationIdInput.value = '';
    reservationIdInput.focus();
}

async function searchReservation() {
    const reservationId = reservationIdInput.value.trim();
    
    if (!reservationId) {
        reservationIdInput.focus();
        return;
    }
    
    // Afficher l'état de chargement :D
    reservationInputZone.style.display = 'none';
    loadingSpinner.style.display = 'block';
    ticketsDisplay.style.display = 'none';
    errorMessage.style.display = 'none';
    
    try {
        // Obtenir les détails de la réservation :p
        const response = await fetch(`${API_BASE_URL}/reservation/${reservationId}`);
        
        if (!response.ok) {
            throw new Error('Reservation not found');
        }
        
        const reservationData = await response.json();
        
        // Récupérer les passagers et les véhicules associés
        const passagers = [];
        const vehicules = [];
        
        for (let i = 1; i <= reservationData.nbPassagers; i++) {
            try {
                const passengerResponse = await fetch(`${API_BASE_URL}/reservation/${reservationId}/passager/${i}`);
                if (passengerResponse.ok) {
                    const passenger = await passengerResponse.json();
                    passagers.push(passenger);
                }
            } catch (error) {
                console.error(`Error fetching passenger ${i}:`, error);
            }
        }
        
        for (let i = 1; i <= reservationData.nbVehicules; i++) {
            try {
                const vehicleResponse = await fetch(`${API_BASE_URL}/reservation/${reservationId}/vehicule/${i}`);
                if (vehicleResponse.ok) {
                    const vehicle = await vehicleResponse.json();
                    vehicules.push(vehicle);
                }
            } catch (error) {
                console.error(`Error fetching vehicle ${i}:`, error);
            }
        }
        
        // Combiner
        const fullReservation = {
            reservation: reservationData,
            passagers: passagers,
            vehicules: vehicules
        };
        
        displayReservation(fullReservation);
        
    } catch (error) {
        // état d'erreur
        loadingSpinner.style.display = 'none';
        errorMessage.style.display = 'block';
        errorText.textContent = 'Réservation introuvable. Veuillez vérifier votre identifiant.';
        console.error('Error fetching reservation:', error);
    }
}

function displayReservation(data) {
    loadingSpinner.style.display = 'none';
    ticketsDisplay.style.display = 'block';
    
    const reservation = data.reservation;
    
    // Nom
    reservationName.textContent = `Réservation - ${reservation.nom || 'N/A'}`;
    
    // HTML Constructeur
    let html = `
        <section class="info-section">
            <h4 class="info-section-title">Informations de réservation</h4>
            <dl class="info-grid">
                <div class="info-item">
                    <dt class="info-label">Nom</dt>
                    <dd class="info-value large">${reservation.nom || 'N/A'}</dd>
                </div>
                <div class="info-item">
                    <dt class="info-label">Liaison</dt>
                    <dd class="info-value">${reservation.portDepart} → ${reservation.portArrivee}</dd>
                </div>
                <div class="info-item">
                    <dt class="info-label">Date</dt>
                    <dd class="info-value">${formatDate(reservation.date)}</dd>
                </div>
                <div class="info-item">
                    <dt class="info-label">Heure</dt>
                    <dd class="info-value">${reservation.heure || 'N/A'}</dd>
                </div>
                <div class="info-item">
                    <dt class="info-label">Bateau</dt>
                    <dd class="info-value">${reservation.bateau || 'N/A'}</dd>
                </div>
                <div class="info-item">
                    <dt class="info-label">ID Réservation</dt>
                    <dd class="info-value">#${reservation.id}</dd>
                </div>
            </dl>
        </section>
    `;
    
    // Section des passagers
    if (data.passagers && data.passagers.length > 0) {
        let totalPassengerPrice = 0;
        
        html += `
            <section class="info-section">
                <h4 class="info-section-title">Passagers (${data.passagers.length})</h4>
                <ul class="passengers-list">
        `;
        
        data.passagers.forEach(passager => {
            totalPassengerPrice += passager.price || 0;
            html += `
                <li class="passenger-item">
                    <div>
                        <span class="passenger-name">${passager.prenom} ${passager.nom}</span>
                        <span class="passenger-category">${passager.libelleCategorie}</span>
                    </div>
                    <span class="passenger-price">${passager.price?.toFixed(2) || '0.00'} €</span>
                </li>
            `;
        });
        
        html += `
                </ul>
                <div class="section-total">Total passagers: ${totalPassengerPrice.toFixed(2)} €</div>
            </section>
        `;
    }
    
    // Section des CARS!
    if (data.vehicules && data.vehicules.length > 0) {
        let totalVehiclePrice = 0;
        
        html += `
            <section class="info-section">
                <h4 class="info-section-title">Véhicules</h4>
                <ul class="vehicles-list">
        `;
        
        data.vehicules.forEach(vehicule => {
            totalVehiclePrice += vehicule.prix || 0;
            html += `
                <li class="vehicle-item">
                    <div>
                        <span class="vehicle-name">${vehicule.libelle}</span>
                        <span class="vehicle-category">Quantité: ${vehicule.quantite}</span>
                    </div>
                    <span class="passenger-price">${vehicule.prix?.toFixed(2) || '0.00'} €</span>
                </li>
            `;
        });
        
        html += `
                </ul>
                <div class="section-total">Total véhicules: ${totalVehiclePrice.toFixed(2)} €</div>
            </section>
        `;
    }
    
    // Total...
    const grandTotal = (data.passagers?.reduce((sum, p) => sum + (p.price || 0), 0) || 0) + 
                       (data.vehicules?.reduce((sum, v) => sum + (v.prix || 0), 0) || 0);
    
    html += `
        <div class="grand-total">
            <span>Total de la réservation</span>
            <span>${grandTotal.toFixed(2)} €</span>
        </div>
    `;
    
    reservationInfo.innerHTML = html;
}

function formatDate(dateStr) {
    if (!dateStr) return 'N/A';
    const date = new Date(dateStr);
    return date.toLocaleDateString('fr-FR', { 
        day: '2-digit', 
        month: 'long', 
        year: 'numeric' 
    });
}

function formatDateTime(dateTimeStr) {
    if (!dateTimeStr) return 'N/A';
    const date = new Date(dateTimeStr);
    return date.toLocaleDateString('fr-FR', { 
        day: '2-digit', 
        month: 'short', 
        year: 'numeric',
        hour: '2-digit',
        minute: '2-digit'
    });
}